/**
 * Table model for memory search results.
 */
public class MemoryMatchTableModel : AddressBasedTableModel<MemoryMatch<SearchData>> {
	private Color CHANGED_COLOR = Tables.ERROR_UNSELECTED;
	private Color CHANGED_SELECTED_COLOR = Tables.ERROR_SELECTED;

	private MemoryMatchTableLoader loader;

	MemoryMatchTableModel(ServiceProvider serviceProvider, Program program) : base("Memory Search", serviceProvider, program, null, true)
    {
	}

	/* @Override */
	protected TableColumnDescriptor<MemoryMatch<SearchData>> createTableColumnDescriptor() {
		TableColumnDescriptor<MemoryMatch<SearchData>> descriptor = new();

		descriptor.addVisibleColumn(
			DiscoverableTableUtils.adaptColumForModel(this, new AddressTableColumn()), 1, true);
		descriptor.addVisibleColumn(new MatchBytesColumn());
		descriptor.addVisibleColumn(new MatchValueColumn());
		descriptor.addVisibleColumn(
			DiscoverableTableUtils.adaptColumForModel(this, new LabelTableColumn()));
		descriptor.addVisibleColumn(
			DiscoverableTableUtils.adaptColumForModel(this, new CodeUnitTableColumn()));

		return descriptor;
	}

	/* @Override */
	protected void doLoad(Accumulator<MemoryMatch<SearchData>> accumulator, TaskMonitor monitor)
    {
		if (loader == null) {
			return;
		}
		loader.loadResults(accumulator, monitor);
		loader = null;
	}

	/* @Override */
	protected void startInitialLoad() {
		// Don't start up a load
	}
	
	void setLoader(MemoryMatchTableLoader loader) {
		this.loader = loader;
		reload();
	}

	public bool isSortedOnAddress() {
		TableSortState sortState = getTableSortState();
		if (sortState.isUnsorted()) {
			return false;
		}

		ColumnSortState primaryState = sortState.getAllSortStates().get(0);
		DynamicTableColumn<MemoryMatch<SearchData>,object,object> column =
			getColumn(primaryState.getColumnModelIndex());
		string name = column.getColumnName();
		if (AddressTableColumn.NAME.equals(name)) {
			return true;
		}
		return false;
	}

	/* @Override */
	public ProgramLocation getProgramLocation(int modelRow, int modelColumn) {
		Program p = getProgram();
		if (p == null) {
			return null; // we've been disposed
		}

		DynamicTableColumn<MemoryMatch<SearchData>,object,object> column = getColumn(modelColumn);
		Class<object> columnClass = column.GetType();
		if (column is MappedTableColumn mappedColumn) {
			columnClass = mappedColumn.getMappedColumnClass();
		}
		if (columnClass == typeof(AddressTableColumn) || columnClass == typeof(MatchBytesColumn) ||
			columnClass == typeof(MatchValueColumn)) {
			return new BytesFieldLocation(p, getAddress(modelRow));
		}

		return base.getProgramLocation(modelRow, modelColumn);
	}

	/* @Override */
	public Address getAddress(int row) {
		MemoryMatch result = getRowObject(row);
		return result.getAddress();
	}

	/* @Override */
	public ProgramSelection getProgramSelection(int[] rows) {
		AddressSet addressSet = new AddressSet();
		foreach (int row in rows) {
			MemoryMatch result = getRowObject(row);
			int addOn = result.getLength() - 1;
			Address minAddr = getAddress(row);
			Address maxAddr = minAddr;
			try {
				maxAddr = minAddr.addNoWrap(addOn);
				addressSet.addRange(minAddr, maxAddr);
			}
			catch (AddressOverflowException e) {
				// I guess we don't care--not sure why this is undocumented :(
			}
		}
		return new ProgramSelection(addressSet);
	}

	public class MatchBytesColumn : DynamicTableColumnExtensionPoint<MemoryMatch<SearchData>, string, Program> {

		private ByteArrayRenderer renderer = new ByteArrayRenderer();

		/* @Override */
		public string getColumnName() {
			return "Match Bytes";
		}

		/* @Override */
		public string getValue(MemoryMatch<SearchData> match, Settings settings, Program pgm,
				ServiceProvider service)
    {

			return getByteString(match.getBytes());
		}

		private string getByteString(byte[] bytes) {
			StringBuilder b = new StringBuilder();
			int max = bytes.length - 1;
			for (int i = 0;; i++) {
				b.append(string.format("%02x", bytes[i]));
				if (i == max) {
					break;
				}
				b.append(" ");
			}
			return b.toString();
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 200;
		}

		/* @Override */
		public GColumnRenderer<string> getColumnRenderer() {
			return renderer;
		}
	}

	public class MatchValueColumn : DynamicTableColumnExtensionPoint<MemoryMatch<SearchData>, string, Program> {

		private ValueRenderer renderer = new ValueRenderer();

		/* @Override */
		public string getColumnName() {
			return "Match Value";
		}

		/* @Override */
		public string getValue(MemoryMatch<SearchData> match, Settings settings, Program pgm,
				ServiceProvider service)
    {

			SearchData searchData = match.getPattern();
			SearchSettings searchSettings = searchData.getSettings();
			SearchFormat format = searchSettings.getSearchFormat();
			return format.getValueString(match.getBytes(), searchSettings);
		}

		/* @Override */
		public int getColumnPreferredWidth() {
			return 200;
		}

		/* @Override */
		public GColumnRenderer<string> getColumnRenderer() {
			return renderer;
		}
	}

	private class ByteArrayRenderer : AbstractGColumnRenderer<string> {
		public ByteArrayRenderer() {
			setHTMLRenderingEnabled(true);
		}

		/* @Override */
		protected Font getDefaultFont() {
			return fixedWidthFont;
		}

		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {
			base.getTableCellRendererComponent(data);
			MemoryMatch<SearchData> match = (MemoryMatch<SearchData>) data.getRowObject();
			string text = data.getValue().toString();
			if (match.isChanged()) {
				text = getHtmlColoredString(match, data.isSelected());
			}
			setText(text);
			return this;
		}

		private string getHtmlColoredString(MemoryMatch<SearchData> match, bool isSelected) {
			Color color = isSelected ? Tables.ERROR_SELECTED : Tables.ERROR_UNSELECTED;

			StringBuilder b = new StringBuilder();
			b.append("<HTML>");
			byte[] bytes = match.getBytes();
			byte[] previousBytes = match.getPreviousBytes();
			int max = bytes.length - 1;
			for (int i = 0;; i++) {
				string byteString = string.format("%02x", bytes[i]);
				if (bytes[i] != previousBytes[i]) {
					byteString = HTMLUtilities.colorString(color, byteString);
				}
				b.append(byteString);
				if (i == max) {
					break;
				}
				b.append(" ");
			}

			return b.toString();
		}

		/* @Override */
		public string getFilterString(string t, Settings settings) {
			// This returns the formatted string without the formatted markup
			return t;
		}
	}

	private class ValueRenderer : AbstractGColumnRenderer<string> {

		/* @Override */
		public Component getTableCellRendererComponent(GTableCellRenderingData data) {
			base.getTableCellRendererComponent(data);
			setText((string) data.getValue());

			MemoryMatch<SearchData> match = (MemoryMatch<SearchData>) data.getRowObject();
			if (match.isChanged()) {
				setForeground(data.isSelected() ? CHANGED_SELECTED_COLOR : CHANGED_COLOR);
			}
			return this;
		}

		/* @Override */
		public string getFilterString(string t, Settings settings) {
			return t;
		}
	}

